static const struct route routes[] = {
    { "/orders/", orders_show },
    { "/",        home_page  },
    { NULL,        NULL       },            /* sentinel */
};
const struct route *r = match_route(routes, req->url);   /* dispatcher */
struct response res = { .status = 200 };
r->worker(req, &res);      /* worker fills the model, never the markup */
render(&res, conn);        /* one render step for every worker */
